         May 19th Election 




        // Function to get the current date and time in the Idaho time zone
        function getCurrentTimeInIdaho() {
            return new Date(new Date().toLocaleString("en-US", {timeZone: "America/Boise"}));
        }

        // Set the date we're counting down to (in Idaho time)
        var countDownDate = new Date("May 19, 2026 08:00:00");

        // Update the countdown every 1 second
        var x = setInterval(function() {
            // Get the current date and time in Idaho time zone
            var now = getCurrentTimeInIdaho().getTime();

            // Calculate the distance between now and the countdown date
            var distance = countDownDate - now;

            // If the countdown is finished, display a message
            if (distance < 0) {
                clearInterval(x);
                document.getElementById("countdown").innerHTML = "-----";
                return;
            }

            // Calculate days, hours, minutes and seconds
            var days = Math.floor(distance / (1000 * 60 * 60 * 24));
            var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
            var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
            var seconds = Math.floor((distance % (1000 * 60)) / 1000);

            // Display the countdown
            document.getElementById("countdown").innerHTML = days + "d | " + hours + "h | " + minutes + "m | " + seconds + "s";
        }, 1000);




















